import 'package:flutter/material.dart'; class ProgressWidget extends StatelessWidget { final double value; const ProgressWidget({super.key,required this.value}); @override Widget build(BuildContext c)=>Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('التقدم: ${value.toStringAsFixed(0)}%'),const SizedBox(height:6),LinearProgressIndicator(value:(value/100).clamp(0,1))]); }